# -*- coding: utf-8 -*-
ICO_B64 = ""

import sys
import tkinter as tk
from tkinter import messagebox
from datetime import date
import base64, io


# ── 고해상도(HiDPI) 모니터 대응 ────────────────────────────────────
#   모니터를 바꾼 뒤 글자가 뿌옇게 번지는 현상은 프로세스가 DPI 인식을
#   하지 않아 Windows가 저해상도 화면을 강제 확대하기 때문이다.
#   Tk 생성 전에 DPI 인식을 켜면 원래 해상도로 선명하게 렌더링된다.

def enable_hidpi():
    """프로세스를 per-monitor DPI 인식으로 설정하고 96DPI 기준 배율을 돌려준다."""
    if not sys.platform.startswith("win"):
        return 1.0
    import ctypes
    try:
        ctypes.windll.user32.SetProcessDpiAwarenessContext(-4)  # PER_MONITOR_AWARE_V2
    except Exception:
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(2)      # PER_MONITOR_AWARE
        except Exception:
            try:
                ctypes.windll.user32.SetProcessDPIAware()
            except Exception:
                pass
    try:
        return max(1.0, ctypes.windll.user32.GetDpiForSystem() / 96.0)
    except Exception:
        return 1.0


# ── 계산 로직 ─────────────────────────────────────────────────────

def elapsed_months(start, today):
    if today < start: return 0
    y = today.year - start.year
    m = today.month - start.month
    if today.day < start.day: m -= 1
    if m < 0: y -= 1; m += 12
    return y * 12 + m

def remaining_balance(p, rate, n, paid):
    r = rate / 12
    if paid <= 0: return p
    if paid >= n: return 0.0
    M = p * r * (1+r)**n / ((1+r)**n - 1)
    for _ in range(paid):
        p -= (M - p * r)
    return p

def calc_mortgage(amount, is_loan, recv=None, today=None):
    if today is None: today = date.today()
    res = {"채권최고액": amount, "기준일": today, "접수일자": None, "경과월수": None}
    if is_loan:
        p = amount / 150 * 100
        res.update({"구분": "대부/개인", "대출원금": p, "저당액": p,
                    "방식": "대부/개인: 채권최고액÷150×100 (기간계산 없음)"})
        return res
    p = amount / 120 * 100
    res.update({"구분": "은행", "대출원금": p})
    if recv is None: raise ValueError("은행 케이스는 접수일자 필요")
    m = elapsed_months(recv, today)
    res.update({"경과월수": m, "접수일자": recv})
    if m < 1:
        res.update({"저당액": p, "방식": "은행: 채권최고액÷120×100 (접수 1개월 미만, 원금 그대로)"})
    else:
        b = remaining_balance(p, 0.03, 240, m)
        res.update({"저당액": b, "방식": f"은행: 채권최고액÷120×100 → 20년/연3% 원리금균등상환 → {m}개월 경과 잔액"})
    return res


# ── 테마 (라이트 / 다크) ──────────────────────────────────────────
#   다크모드에서 라벨(TXT3)·힌트(TXT4)가 배경 대비 너무 어두워 잘 안 보이던
#   문제를 밝은 회색으로 올려 가독성을 개선했다.

THEMES = {
    "dark": {
        "BG":   "#1C1C1E",   # 앱 배경
        "BG2":  "#2C2C2E",   # 입력/버튼 배경
        "BG3":  "#3A3A3C",   # 테두리/비활성
        "OR":   "#FF9F0A",   # 오렌지 강조
        "OR_ACT": "#E8910A",
        "TXT":  "#FFFFFF",   # 기본 글자
        "TXT2": "#AEAEB2",   # 보조(초기화 버튼)
        "TXT3": "#98989D",   # 라벨 (기존 #636366 → 밝게)
        "TXT4": "#8E8E93",   # 힌트/비활성 (기존 #48484A → 밝게)
        "TOGGLE_LABEL": "○ 라이트 모드",
    },
    "light": {
        "BG":   "#F2F2F7",
        "BG2":  "#FFFFFF",
        "BG3":  "#C7C7CC",
        "OR":   "#FF9500",
        "OR_ACT": "#E8850A",
        "TXT":  "#1C1C1E",
        "TXT2": "#3A3A3C",
        "TXT3": "#6C6C70",
        "TXT4": "#8E8E93",
        "TOGGLE_LABEL": "● 다크 모드",
    },
}


def F(size, bold=False):
    return ("맑은 고딕", size, "bold" if bold else "normal")


# ── 근저당권자 토글 버튼 ──────────────────────────────────────────

class Toggle(tk.Frame):
    def __init__(self, parent, app, text, active=False, cmd=None):
        super().__init__(parent, highlightthickness=0, cursor="hand2")
        self.app = app
        self._cmd = cmd
        self._active = active
        self._lbl = tk.Label(self, text=text, font=F(12, True), padx=0, pady=10)
        self._lbl.pack(fill="both", expand=True)
        for w in (self, self._lbl):
            w.bind("<ButtonRelease-1>", lambda e: self._cmd() if self._cmd else None)
        self.retheme()

    def activate(self, on):
        self._active = on
        self.retheme()

    def retheme(self):
        C = self.app.C
        bg = C["OR"] if self._active else C["BG2"]
        fg = "#000000" if self._active else C["TXT3"]
        self.configure(bg=bg)
        self._lbl.configure(bg=bg, fg=fg)


# ── 메인 앱 ──────────────────────────────────────────────────────

class App(tk.Tk):
    def __init__(self, scale: float = 1.0, theme: str = "dark"):
        super().__init__()
        self.scale = scale
        # 포인트 폰트가 배율에 맞춰 커지도록 Tk 스케일링 지정 → 선명 유지
        try:
            self.tk.call("tk", "scaling", scale * 96.0 / 72.0)
        except Exception:
            pass
        self.theme_name = theme if theme in THEMES else "dark"
        self.C = THEMES[self.theme_name]
        self._themed = []     # (위젯, 역할) - 테마 전환 시 다시 칠함

        self.title("저당액 계산기")
        self.resizable(False, False)
        self.geometry(f"{int(380 * scale)}x{int(680 * scale)}")
        self._set_icon()
        self.creditor = tk.StringVar(value="은행")
        self._res = None
        self._build()
        self._apply_theme()

    def _set_icon(self):
        # 창(타이틀바) 아이콘을 앱 아이콘(mortgage_icon_dark.ico)과 동일하게 표시
        try:
            from PIL import Image, ImageTk
            data = base64.b64decode(ICO_B64)
            im = Image.open(io.BytesIO(data)).convert("RGBA").resize((32, 32), Image.LANCZOS)
            self._icon = ImageTk.PhotoImage(im)
            self.iconphoto(True, self._icon)
        except Exception:
            pass

    def _reg(self, w, role):
        self._themed.append((w, role))
        return w

    def _mk_entry(self, parent, width=None, justify="right"):
        C = self.C
        kw = dict(font=F(13, True), fg=C["TXT"], bg=C["BG2"],
                  insertbackground=C["OR"], relief="flat",
                  highlightthickness=1, highlightbackground=C["BG3"],
                  highlightcolor=C["OR"], justify=justify)
        if width:
            kw["width"] = width
        e = tk.Entry(parent, **kw)
        e.bind("<FocusIn>",  lambda ev: ev.widget.configure(highlightbackground=self.C["OR"]))
        e.bind("<FocusOut>", lambda ev: ev.widget.configure(highlightbackground=self.C["BG3"]))
        return self._reg(e, "entry")

    # ── 전체 레이아웃 ─────────────────────────────────────
    def _build(self):
        self.columnconfigure(0, weight=1)
        self.rowconfigure(0, weight=1)   # 디스플레이
        self.rowconfigure(1, weight=0)   # 컨트롤
        self._display()
        self._controls()

    # ── 디스플레이 (상단) ─────────────────────────────────
    def _display(self):
        f = self._reg(tk.Frame(self), "bg")
        f.grid(row=0, column=0, sticky="ew", padx=20, pady=(2, 0))
        f.columnconfigure(0, weight=1)

        # 헤더: 테마 토글(좌) + "저당액"(우)
        header = self._reg(tk.Frame(f), "bg")
        header.grid(row=0, column=0, sticky="ew")
        header.columnconfigure(0, weight=1)
        self.theme_btn = tk.Button(header, text="", font=F(9), relief="flat", bd=0,
                                   cursor="hand2", takefocus=0, command=self._toggle_theme)
        self.theme_btn.grid(row=0, column=0, sticky="w")
        self._reg(tk.Label(header, text="저당액", font=F(16, True), anchor="e"),
                  "title").grid(row=0, column=1, sticky="e")

        # 숫자 + 원 (오른쪽 정렬)
        num_row = self._reg(tk.Frame(f), "bg")
        num_row.grid(row=1, column=0, sticky="e", pady=(2, 0))
        num_row.columnconfigure(0, weight=1)
        self.num_lbl = self._reg(tk.Label(num_row, text="0",
                                          font=("맑은 고딕", 48, "bold"),
                                          cursor="hand2", anchor="e"), "num")
        self.num_lbl.pack(side="left")
        self.won_lbl = self._reg(tk.Label(num_row, text=" 원", font=F(13), anchor="sw"), "won")
        self.won_lbl.pack(side="left", pady=(12, 0))
        for w in (self.num_lbl, num_row, self.won_lbl):
            w.bind("<Button-1>", self._copy)

        # 복사 안내
        self.copy_hint = self._reg(tk.Label(f, text="숫자를 클릭하면 복사됩니다",
                                            font=F(8), anchor="e"), "hint")
        self.copy_hint.grid(row=2, column=0, sticky="e", pady=(1, 4))

        # 상세 정보
        self.lbl_amount = self._reg(tk.Label(f, text="", font=F(9), anchor="w"), "detail")
        self.lbl_princ  = self._reg(tk.Label(f, text="", font=F(9), anchor="w"), "detail")
        self.lbl_date   = self._reg(tk.Label(f, text="", font=F(9), anchor="w"), "detail")
        self.lbl_today  = self._reg(tk.Label(f, text="", font=F(9), anchor="w"), "detail")
        self.lbl_method = self._reg(tk.Label(f, text="", font=F(9), anchor="w",
                                             wraplength=int(340 * self.scale),
                                             justify="left"), "detail")
        self.lbl_amount.grid(row=3, column=0, sticky="ew")
        self.lbl_princ.grid( row=4, column=0, sticky="ew")
        self.lbl_date.grid(  row=5, column=0, sticky="ew")
        self.lbl_today.grid( row=6, column=0, sticky="ew")
        self.lbl_method.grid(row=7, column=0, sticky="ew", pady=(2, 6))

        # 구분선
        self.sep = self._reg(tk.Frame(self, height=1), "sep")
        self.sep.grid(row=0, column=0, sticky="sew")

    # ── 컨트롤 (하단) ─────────────────────────────────────
    def _controls(self):
        f = self._reg(tk.Frame(self), "bg")
        f.grid(row=1, column=0, sticky="ew", padx=20, pady=(10, 14))
        f.columnconfigure((0, 1), weight=1)

        # ① 근저당권자 토글
        self._form_label("근저당권자", f, row=0)
        self.tb_bank = Toggle(f, self, "은행",     active=True,  cmd=lambda: self._sel("은행"))
        self.tb_loan = Toggle(f, self, "대부 / 개인", active=False, cmd=lambda: self._sel("대부"))
        self.tb_bank.grid(row=1, column=0, sticky="ew", padx=(0, 5), pady=(4, 8))
        self.tb_loan.grid(row=1, column=1, sticky="ew", padx=(5, 0), pady=(4, 8))

        # ② 채권최고액
        self._form_label("채권최고액 (원)", f, row=2)
        self.amt = self._mk_entry(f)
        self.amt.grid(row=3, column=0, columnspan=2, sticky="ew", pady=(4, 8), ipady=8)

        # ③ 접수일자
        self.dl = self._form_label("접수일자", f, row=4)
        df = self._reg(tk.Frame(f), "bg")
        df.grid(row=5, column=0, columnspan=2, sticky="ew", pady=(4, 8))
        df.columnconfigure((0, 2, 4), weight=1)

        self.ye = self._mk_entry(df, width=6, justify="center")
        self.me = self._mk_entry(df, width=4, justify="center")
        self.de = self._mk_entry(df, width=4, justify="center")
        self.date_ws = [self.ye, self.me, self.de]

        self.ye.grid(row=0, column=0, sticky="ew", ipady=7)
        self._reg(tk.Label(df, text="년", font=F(11)), "unit").grid(row=0, column=1, padx=6)
        self.me.grid(row=0, column=2, sticky="ew", ipady=7)
        self._reg(tk.Label(df, text="월", font=F(11)), "unit").grid(row=0, column=3, padx=6)
        self.de.grid(row=0, column=4, sticky="ew", ipady=7)
        self.de.bind("<Return>", lambda e: self._calc())
        self._reg(tk.Label(df, text="일", font=F(11)), "unit").grid(row=0, column=5, padx=6)

        # ④ 계산 / 초기화
        btn_row = self._reg(tk.Frame(f), "bg")
        btn_row.grid(row=6, column=0, columnspan=2, sticky="ew", pady=(4, 0))
        btn_row.columnconfigure(0, weight=3)
        btn_row.columnconfigure(1, weight=1)

        self.calc_btn = tk.Button(btn_row, text="계산", font=F(14, True),
                                  relief="flat", bd=0, pady=10, cursor="hand2",
                                  command=self._calc)
        self.calc_btn.grid(row=0, column=0, sticky="ew", padx=(0, 6))
        self._reg(self.calc_btn, "calc")

        self.reset_btn = tk.Button(btn_row, text="초기화", font=F(14, True),
                                   relief="flat", bd=0, pady=10, cursor="hand2",
                                   command=self._reset)
        self.reset_btn.grid(row=0, column=1, sticky="ew")
        self._reg(self.reset_btn, "reset")

    def _form_label(self, text, parent, row):
        l = self._reg(tk.Label(parent, text=text, font=F(10), anchor="w"), "form")
        l.grid(row=row, column=0, columnspan=2, sticky="w")
        return l

    # ── 테마 적용 / 전환 ─────────────────────────────────
    def _apply_theme(self):
        C = self.C
        self.configure(bg=C["BG"])
        for w, role in self._themed:
            if role == "bg":
                w.configure(bg=C["BG"])
            elif role == "title":
                w.configure(bg=C["BG"], fg=C["TXT"])
            elif role == "num":
                w.configure(bg=C["BG"], fg=C["TXT"])
            elif role == "won":
                w.configure(bg=C["BG"], fg=C["TXT3"])
            elif role == "hint":
                w.configure(bg=C["BG"], fg=C["TXT4"])
            elif role == "detail":
                w.configure(bg=C["BG"], fg=C["TXT"])
            elif role == "form":
                w.configure(bg=C["BG"], fg=C["TXT3"])
            elif role == "unit":
                w.configure(bg=C["BG"], fg=C["TXT3"])
            elif role == "sep":
                w.configure(bg=C["BG2"])
            elif role == "entry":
                w.configure(bg=C["BG2"], fg=C["TXT"], insertbackground=C["OR"],
                            highlightbackground=C["BG3"], highlightcolor=C["OR"],
                            disabledbackground=C["BG2"], disabledforeground=C["TXT4"])
            elif role == "calc":
                w.configure(bg=C["OR"], fg="#000000",
                            activebackground=C["OR_ACT"], activeforeground="#000000")
            elif role == "reset":
                w.configure(bg=C["BG2"], fg=C["TXT2"],
                            activebackground=C["BG3"], activeforeground=C["TXT"])
        # 테마 토글 버튼
        self.theme_btn.configure(text=C["TOGGLE_LABEL"], bg=C["BG"], fg=C["TXT3"],
                                 activebackground=C["BG"], activeforeground=C["OR"])
        # 상태 의존 색(토글/날짜칸) 재적용
        self._sel(self.creditor.get())

    def _toggle_theme(self):
        self.theme_name = "light" if self.theme_name == "dark" else "dark"
        self.C = THEMES[self.theme_name]
        self._apply_theme()

    # ── 동작 ─────────────────────────────────────────────
    def _sel(self, val):
        C = self.C
        self.creditor.set(val)
        self.tb_bank.activate(val == "은행")
        self.tb_loan.activate(val == "대부")
        is_bank = (val == "은행")
        for w in self.date_ws:
            w.configure(state="normal" if is_bank else "disabled",
                        fg=C["TXT"] if is_bank else C["TXT4"])
        self.dl.configure(fg=C["TXT3"] if is_bank else C["TXT4"])

    def _calc(self):
        try:
            raw = self.amt.get().strip().replace(",", "")
            if not raw:
                messagebox.showwarning("입력 오류", "채권최고액을 입력해주세요.")
                return
            amount = float(raw)
            is_loan = (self.creditor.get() == "대부")
            recv = None
            if not is_loan:
                y, m, d = (e.get().strip() for e in self.date_ws)
                if not (y and m and d):
                    messagebox.showwarning("입력 오류", "접수일자를 모두 입력해주세요.")
                    return
                try:    recv = date(int(y), int(m), int(d))
                except: messagebox.showwarning("입력 오류", "올바르지 않은 날짜입니다."); return
            r = calc_mortgage(amount, is_loan, recv)
            self._res = r
            self._show(r)
        except Exception as e:
            messagebox.showerror("오류", str(e))

    def _reset(self):
        """입력값과 결과 표시를 모두 초기 상태로 되돌린다."""
        C = self.C
        self.amt.delete(0, tk.END)
        for w in self.date_ws:
            w.configure(state="normal")
            w.delete(0, tk.END)
        self._sel("은행")
        self._res = None
        self.num_lbl.configure(text="0", fg=C["TXT"], font=("맑은 고딕", 48, "bold"))
        self.won_lbl.configure(font=F(13))
        self.copy_hint.configure(text="숫자를 클릭하면 복사됩니다", fg=C["TXT4"])
        for l in (self.lbl_amount, self.lbl_princ, self.lbl_date, self.lbl_today, self.lbl_method):
            l.configure(text="")
        self.amt.focus_set()

    def _auto_font(self, text):
        """숫자+원 합산 너비가 창에 맞는 폰트 크기 탐색 (실제 너비 측정)"""
        max_width = int(340 * self.scale)
        for size in [44, 38, 32, 27, 22, 18]:
            self.num_lbl.configure(font=("맑은 고딕", size, "bold"), text=text)
            self.won_lbl.configure(font=F(max(9, size - 14)))
            self.num_lbl.update_idletasks()
            self.won_lbl.update_idletasks()
            total = self.num_lbl.winfo_reqwidth() + self.won_lbl.winfo_reqwidth()
            if total <= max_width:
                return size
        return 16

    def _show(self, r):
        num_text = f"{r['저당액']:,.0f}"
        self._auto_font(num_text)
        self.lbl_amount.configure(text=f"채권최고액  :  {r['채권최고액']:,.0f} 원")
        self.lbl_princ.configure( text=f"대출원금    :  {r['대출원금']:,.0f} 원")
        if r.get("접수일자"):
            self.lbl_date.configure(text=f"접수일자    :  {r['접수일자']}  ({r['경과월수']}개월 경과)")
        else:
            self.lbl_date.configure(text="접수일자    :  —")
        self.lbl_today.configure(text=f"기준일      :  {r['기준일']}")
        self.lbl_method.configure(text=f"{r['방식']}")

    def _copy(self, e=None):
        if not self._res: return
        C = self.C
        self.clipboard_clear()
        self.clipboard_append(f"{self._res['저당액']:,.0f}")
        self.num_lbl.configure(fg=C["OR"])
        self.copy_hint.configure(text="✔ 복사됨", fg=C["OR"])
        self.after(1500, lambda: [
            self.num_lbl.configure(fg=self.C["TXT"]),
            self.copy_hint.configure(text="숫자를 클릭하면 복사됩니다", fg=self.C["TXT4"])
        ])


if __name__ == "__main__":
    scale = enable_hidpi()   # DPI 인식 활성화 (Tk 생성 전에 호출)
    App(scale).mainloop()
